use bhoo::android_number_picker::NumberPickerState;
#[test] fn wraps_only_when_range_allows_and_preference_survives_changes(){let mut s=NumberPickerState::new(0,2,2).unwrap();assert!(!s.wraps());assert!(!s.step(1));s.set_range(0,3,None).unwrap();assert!(s.wraps());s.set_value(3);assert!(s.step(1));assert_eq!(s.value(),0);assert_eq!(s.neighbor(-1),Some(3));s.set_wrap_preferred(false);assert!(!s.wraps());assert_eq!(s.neighbor(-1),None);s.set_range(0,9,None).unwrap();assert!(!s.wraps());}
#[test] fn range_labels_and_input_validate_transactionally(){let mut s=NumberPickerState::new(1,3,3).unwrap();assert!(s.set_range(1,4,Some(vec!["one".into()])).is_err());assert_eq!((s.min(),s.max(),s.value()),(1,3,3));s.set_range(1,3,Some(["January","February","March"].map(str::to_owned).to_vec())).unwrap();assert_eq!(s.parse_input("feB"),Some(2));assert_eq!(s.parse_input("99"),Some(99));assert_eq!(s.parse_input("unknown"),Some(1));assert_eq!(s.parse_input(""),None);assert_eq!(s.label(2).as_deref(),Some("February"));}
#[test] fn large_out_of_range_values_do_not_overflow(){let mut s=NumberPickerState::new(0,i32::MAX,0).unwrap();assert!(s.set_value(-1));assert_eq!(s.value(),i32::MAX);assert!(s.step(1));assert_eq!(s.value(),0);s.set_wrap_preferred(false);s.set_value(2);assert!(s.set_value(-3));assert_eq!(s.value(),0);}
mod fixture {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_number_picker.rs"));}
#[test] fn xml_wheel_tap_and_touch_drag_update_value(){use bhoo::*;let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.number_pickers.insert("quantity".into(),NumberPickerState::new(0,9,5).unwrap());let b=Rect{x:0.,y:0.,width:120.,height:144.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|{let mut result=None;ui.frame(input,b,0.,|f|result=fixture::LAYOUT.render(f,b,s));result};draw(&mut ui,&mut s,Input::default());let p=[60.,120.];draw(&mut ui,&mut s,Input{pointer:Some(p),pressed:true,time:1.,..Input::default()});assert_eq!(draw(&mut ui,&mut s,Input{pointer:Some(p),released:true,time:1.1,..Input::default()}),Some("quantity"));assert_eq!(s.number_pickers["quantity"].value(),6);draw(&mut ui,&mut s,Input{time:1.5,..Input::default()});let touch=|y,pressed,released,time|Input{pointer:Some([60.,y]),pointer_kind:PointerKind::Touch,pressed,released,time,..Input::default()};draw(&mut ui,&mut s,touch(100.,true,false,2.));assert_eq!(draw(&mut ui,&mut s,touch(60.,false,false,2.1)),Some("quantity"));assert_eq!(s.number_pickers["quantity"].value(),7);draw(&mut ui,&mut s,touch(60.,false,true,2.2));assert_eq!(s.number_pickers["quantity"].value(),7);}
#[test] fn exact_half_row_drag_does_not_oscillate(){use bhoo::*;let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.number_pickers.insert("quantity".into(),NumberPickerState::new(0,9,5).unwrap());let b=Rect{x:0.,y:0.,width:120.,height:144.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|ui.frame(input,b,0.,|f|{fixture::LAYOUT.render(f,b,s);});let touch=|y,pressed,time|Input{pointer:Some([60.,y]),pointer_kind:PointerKind::Touch,pressed,time,..Input::default()};draw(&mut ui,&mut s,Input::default());draw(&mut ui,&mut s,touch(100.,true,1.));draw(&mut ui,&mut s,touch(76.,false,1.1));assert_eq!(s.number_pickers["quantity"].value(),5);}
#[test] fn fling_continues_after_release_and_stops_at_boundary(){use bhoo::*;let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();let mut model=NumberPickerState::new(0,20,5).unwrap();model.set_wrap_preferred(false);s.number_pickers.insert("quantity".into(),model);let b=Rect{x:0.,y:0.,width:120.,height:144.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|ui.frame(input,b,0.,|f|{fixture::LAYOUT.render(f,b,s);});let touch=|y,pressed,released,time|Input{pointer:Some([60.,y]),pointer_kind:PointerKind::Touch,pressed,released,time,..Input::default()};draw(&mut ui,&mut s,Input::default());draw(&mut ui,&mut s,touch(110.,true,false,1.));draw(&mut ui,&mut s,touch(55.,false,false,1.04));draw(&mut ui,&mut s,touch(55.,false,true,1.05));let released=s.number_pickers["quantity"].value();for i in 1..=120 {draw(&mut ui,&mut s,Input{time:1.05+i as f64*0.016,..Input::default()});}assert!(s.number_pickers["quantity"].value()>released);assert!(s.number_pickers["quantity"].value()<=20);}
#[test] fn holding_repeats_and_release_does_not_add_extra_click(){use bhoo::*;let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.number_pickers.insert("quantity".into(),NumberPickerState::new(0,9,3).unwrap());let b=Rect{x:0.,y:0.,width:120.,height:144.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|ui.frame(input,b,0.,|f|{fixture::LAYOUT.render(f,b,s);});let input=|pressed,released,time|Input{pointer:Some([60.,120.]),pressed,released,time,..Input::default()};draw(&mut ui,&mut s,Input::default());draw(&mut ui,&mut s,input(true,false,1.));draw(&mut ui,&mut s,input(false,false,1.51));assert_eq!(s.number_pickers["quantity"].value(),4);draw(&mut ui,&mut s,input(false,false,1.82));assert_eq!(s.number_pickers["quantity"].value(),5);draw(&mut ui,&mut s,input(false,true,1.83));assert_eq!(s.number_pickers["quantity"].value(),5);}
#[test] fn editing_commits_or_cancels_and_reports_only_changes(){use bhoo::*;let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.number_pickers.insert("quantity".into(),NumberPickerState::new(0,9,5).unwrap());let b=Rect{x:0.,y:0.,width:120.,height:144.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|{let mut a=None;ui.frame(input,b,0.,|f|a=fixture::LAYOUT.render(f,b,s));a};draw(&mut ui,&mut s,Input::default());let click=|ui:&mut Ui,s:&mut android_xml::LayoutState,t:f64|{let p=Some([60.,72.]);draw(ui,s,Input{pointer:p,pressed:true,time:t,..Input::default()});draw(ui,s,Input{pointer:p,released:true,time:t+0.01,..Input::default()});};click(&mut ui,&mut s,1.);assert!(s.number_picker_editing.contains("quantity"));assert_eq!(s.text["quantity"],"5");s.text.insert("quantity".into(),"8".into());assert!(s.end_number_picker_edit("quantity",true));assert_eq!(draw(&mut ui,&mut s,Input{time:1.1,..Input::default()}),Some("quantity"));assert_eq!(s.number_pickers["quantity"].value(),8);click(&mut ui,&mut s,2.);s.text.insert("quantity".into(),"2".into());assert!(!s.end_number_picker_edit("quantity",false));assert_eq!(s.number_pickers["quantity"].value(),8);assert_eq!(draw(&mut ui,&mut s,Input{time:2.1,..Input::default()}),None);}
#[test] fn localized_digits_are_displayed_and_accepted(){use bhoo::*;let mut ui=Ui::default();let mut s=android_xml::LayoutState::default();s.calendar_locale.digits=["۰","۱","۲","۳","۴","۵","۶","۷","۸","۹"].map(str::to_owned);s.number_pickers.insert("quantity".into(),NumberPickerState::new(0,9,5).unwrap());let b=Rect{x:0.,y:0.,width:120.,height:144.};let draw=|ui:&mut Ui,s:&mut android_xml::LayoutState,input|ui.frame(input,b,0.,|f|{fixture::LAYOUT.render(f,b,s);});let commands=draw(&mut ui,&mut s,Input::default());assert!(commands.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="۵")));let p=Some([60.,72.]);draw(&mut ui,&mut s,Input{pointer:p,pressed:true,time:1.,..Input::default()});draw(&mut ui,&mut s,Input{pointer:p,released:true,time:1.01,..Input::default()});assert_eq!(s.text["quantity"],"۵");s.text.insert("quantity".into(),"۸".into());assert!(s.end_number_picker_edit("quantity",true));assert_eq!(s.number_pickers["quantity"].value(),8);assert_eq!(s.number_pickers["quantity"].parse_input_localized("۷",&s.calendar_locale.digits),Some(7));assert_eq!(s.number_pickers["quantity"].parse_input_localized("7",&s.calendar_locale.digits),Some(7));}
